// 1. JSX 编译对比
// 源码：<div className="app"><h1>Hello</h1><p>World</p></div>

// React 17+ automatic runtime（Babel/SWC 自动注入 import）
import { jsx as _jsx, jsxs as _jsxs } from 'react/jsx-runtime';
_jsxs('div', {
  className: 'app',
  children: [
    _jsx('h1', { children: 'Hello' }),
    _jsx('p', { children: 'World' })
  ]
});

// 旧 runtime（需要 import React）
React.createElement(
  'div', { className: 'app' },
  React.createElement('h1', null, 'Hello'),
  React.createElement('p', null, 'World')
);

// 2. Fiber 节点核心结构
const fiber = {
  tag: 5,                // HostComponent（5 表示原生 DOM 元素）
  type: 'div',          // 标签名或组件函数/类
  stateNode: domNode,   // 对应的真实 DOM 节点
  props: { className: 'app', children: [...] },
  child: childFiber,    // 第一个子 Fiber
  sibling: siblingFiber,// 下一个兄弟 Fiber
  return: parentFiber,  // 父 Fiber
  alternate: prevFiber, // 另一棵树（current ↔ workInProgress）的对应 Fiber
  flags: 0b0000000000000010, // Update 副作用标记
  lanes: 0b0000000000000000000000000000001, // SyncLane
  memoizedState: null,  // hooks 链表头
};

// 3. 简化的 work loop（对应 React 内部逻辑）
let nextUnitOfWork = rootFiber;
let shouldYield = false;

function workLoop() {
  while (nextUnitOfWork !== null && !shouldYield) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  if (nextUnitOfWork === null) {
    commitRoot(); // render 完成，进入不可中断的 commit 阶段
  } else {
    // 时间切片用完，让出主线程，下个空闲期继续
    scheduleCallback(workLoop);
  }
}

function performUnitOfWork(unit) {
  // beginWork：对当前 fiber 做 reconcile，生成子 fiber
  const next = beginWork(unit);
  if (next) return next; // 有子节点就继续往下
  // completeWork：往上回溯，收集副作用到 effectList
  let current = unit;
  while (current !== null) {
    completeWork(current);
    if (current.sibling) return current.sibling;
    current = current.return;
  }
  return null;
}

